exercises.solution:
def sign(n):
    if n > 0:
        return 1
    if n < 0:
        return -1
    return 0

def letter_grade(score):
    if score >= 90:
        return 'A'
    if score >= 80:
        return 'B'
    if score >= 70:
        return 'C'
    if score >= 60:
        return 'D'
    return 'F'

